@page "/notepad"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea class="form-control mb-3" rows="12" @bind="content" @bind:event="oninput"
          placeholder="Type your notes here..."></textarea>

<div class="d-flex align-items-center gap-3">
    <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
    <button class="btn btn-outline-danger" @onclick="ClearAsync">Clear</button>
    @if (lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string savedContent = string.Empty;
    private DateTime? lastSavedAt;
    private IJSObjectReference? module;
    private Timer? autoSaveTimer;

    private const string StorageKeyContent = "notepad-content";
    private const string StorageKeyTimestamp = "notepad-timestamp";

    private bool HasUnsavedChanges => content != savedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        module = await JS.InvokeAsync<IJSObjectReference>(
            "import", Assets["Components/Pages/Notepad.razor.js"]);

        var stored = await module.InvokeAsync<string?>("load", StorageKeyContent);
        if (!string.IsNullOrEmpty(stored))
        {
            content = stored;
            savedContent = stored;

            var ts = await module.InvokeAsync<string?>("load", StorageKeyTimestamp);
            if (DateTime.TryParse(ts, out var parsed))
                lastSavedAt = parsed;

            StateHasChanged();
        }

        autoSaveTimer = new Timer(async _ =>
        {
            if (HasUnsavedChanges)
                await InvokeAsync(SaveNowAsync);
        }, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));

        await module.InvokeVoidAsync("registerBeforeUnload");
        await UpdateDirtyFlag();
    }

    private async Task SaveNowAsync()
    {
        if (module is null) return;

        lastSavedAt = DateTime.Now;
        savedContent = content;

        await module.InvokeVoidAsync("save", StorageKeyContent, content);
        await module.InvokeVoidAsync("save", StorageKeyTimestamp, lastSavedAt.Value.ToString("O"));
        await UpdateDirtyFlag();

        StateHasChanged();
    }

    private async Task ClearAsync()
    {
        if (module is null) return;

        content = string.Empty;
        savedContent = string.Empty;
        lastSavedAt = null;

        await module.InvokeVoidAsync("remove", StorageKeyContent);
        await module.InvokeVoidAsync("remove", StorageKeyTimestamp);
        await UpdateDirtyFlag();
    }

    private async Task UpdateDirtyFlag()
    {
        if (module is not null)
            await module.InvokeVoidAsync("setDirty", HasUnsavedChanges);
    }

    public async ValueTask DisposeAsync()
    {
        autoSaveTimer?.Dispose();

        if (module is not null)
        {
            try
            {
                await module.InvokeVoidAsync("unregisterBeforeUnload");
                await module.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }
    }
}

let dirty = false;

function onBeforeUnload(e) {
    if (dirty) {
        e.preventDefault();
    }
}

export function save(key, value) {
    localStorage.setItem(key, value);
}

export function load(key) {
    return localStorage.getItem(key);
}

export function remove(key) {
    localStorage.removeItem(key);
}

export function setDirty(isDirty) {
    dirty = isDirty;
}

export function registerBeforeUnload() {
    window.addEventListener("beforeunload", onBeforeUnload);
}

export function unregisterBeforeUnload() {
    window.removeEventListener("beforeunload", onBeforeUnload);
}

